 22	      );
 23	    }
 24	
 25	    this.s3 = new S3Client({
 26	      region: "auto",
 27	      endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
 28	      credentials: { accessKeyId, secretAccessKey },
 29	    });
 30	    this.bucket = bucket;
 31	    this.publicUrl = `https://${bucket}.${accountId}.r2.dev`;
 32	  }
 33	
 34	  async uploadObject(
 35	    key: string,
 36	    body: Buffer | Uint8Array,
 37	    contentType: string,
 38	  ): Promise<void> {
 39	    await this.s3.send(
 40	      new PutObjectCommand({
 41	        Bucket: this.bucket,
 42	        Key: key,
 43	        Body: body,
 44	        ContentType: contentType,
 45	      }),
 46	    );
 47	  }
 48	
