 53	  async getObject(
 54	    key: string,
 55	  ): Promise<{ body: Buffer; contentType: string } | null> {
 56	    try {
 57	      const response = await this.s3.send(
 58	        new GetObjectCommand({
 59	          Bucket: this.bucket,
 60	          Key: key,
 61	        }),
 62	      );
 63	
 64	      if (!response.Body) return null;
 65	
 66	      const chunks: Uint8Array[] = [];
 67	      const stream = response.Body as AsyncIterable<Uint8Array>;
 68	      for await (const chunk of stream) {
 69	        chunks.push(chunk);
 70	      }
 71	
 72	      return {
 73	        body: Buffer.concat(chunks),
 74	        contentType: response.ContentType || "application/octet-stream",
 75	      };
 76	    } catch {
 77	      return null;
 78	    }
 79	  }
