122	      initializedRef.current = true;
123	    }
124	
125	    onEditor?.(editor);
126	
127	    const sync = () => {
128	      onChange({
129	        html: buildHtml(editor),
130	        design: editor.getProjectData(),
131	      });
132	    };
133	
134	    editor.on("update", sync);
135	    editor.on("destroy", () => {
136	      editor.off("update", sync);
137	    });
138	    sync();
139	  }
140	
141	  return (
142	    <div className="overflow-hidden rounded-2xl border border-[#1C2945] bg-white shadow-[0_24px_60px_rgba(2,11,29,0.35)]">
143	      <GjsEditor
144	        grapesjs={grapesjs}
145	        grapesjsCss="https://unpkg.com/grapesjs/dist/css/grapes.min.css"
146	        onEditor={handleEditor}
147	        options={{
148	          height: "720px",
149	          storageManager: false,
150	          noticeOnUnload: false,
151	          plugins,
152	          pluginsOpts,
153	        }}
154	      />
155	    </div>
156	  );
157	}

